import 'dart:async';
import 'package:flutter/material.dart';
import '../../services/payment_api.dart';
class PaymentStatusScreen extends StatefulWidget { final PaymentIntent intent; const PaymentStatusScreen({super.key,required this.intent}); @override State<PaymentStatusScreen> createState()=>_PaymentStatusScreenState(); }
class _PaymentStatusScreenState extends State<PaymentStatusScreen>{ late PaymentIntent intent; Timer? timer; @override void initState(){super.initState();intent=widget.intent;timer=Timer.periodic(const Duration(seconds:3),(_)=>_poll());} Future<void> _poll()async{if(!mounted||intent.status!='PENDING'){timer?.cancel();return;}try{final n=await PaymentApi().getIntent(intent.id);if(mounted)setState(()=>intent=n);if(n.status!='PENDING')timer?.cancel();}catch(_){}} @override void dispose(){timer?.cancel();super.dispose();} @override Widget build(BuildContext context){final pending=intent.status=='PENDING';return Scaffold(appBar:AppBar(title:const Text('Payment status')),body:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(intent.type=='DEPOSIT'?'Deposit':'Withdrawal',style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:12),Text('${intent.currency} ${intent.amount.toStringAsFixed(2)}',style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:20),Row(children:[Icon(pending?Icons.hourglass_top:intent.status=='SUCCEEDED'?Icons.check_circle:Icons.error),const SizedBox(width:10),Text(intent.status)]),const SizedBox(height:12),const Text('TradeSphere changes the ledger only after verified provider confirmation.')]));}}
